/**
 * ACC Observation Report PDF generator
 * ------------------------------------
 * Generates a CoachRICE-branded ACC Observation Report PDF using jsPDF +
 * jsPDF-AutoTable. Table rows grow automatically to fit their content
 * (behavioral statement text, Evidence/Contra-evidence notes, and the
 * Evaluation Summary) instead of using fixed-size cells, and the real
 * Montserrat font (Regular + Bold) is embedded directly in the PDF so it
 * doesn't fall back to a generic PDF font.
 *
 * DEPENDENCIES (load before this file, e.g. via CDN <script> tags):
 *   https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js
 *   https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js
 * (Or install as npm packages: jspdf@2.5.1, jspdf-autotable@3.8.2 -- if
 * using npm, replace `const { jsPDF } = window.jspdf;` inside
 * generateACCObservationReportPDF() with a normal import instead.)
 *
 * USAGE:
 *   const doc = generateACCObservationReportPDF({
 *     coachName: "Jordan Rivera",
 *     sessionDate: "08/10/2026",
 *     assessorName: "CoachRICE Transcript Reviewer", // optional, this is the default
 *     observed: { item1: "Observed", a3_1: "Observed", ... },
 *     evidenceNotes: { item1: "12:34, 13:02", a3_1: "01:15", ... },
 *     summaryStrengths: "...",
 *     summarySuggestions: "...",
 *   });
 *   doc.save("ACC_Observation_Report.pdf");
 *   // or: const bytes = await doc.output('arraybuffer');
 *
 * Field IDs (the keys used in `observed` and `evidenceNotes` above) are
 * listed in SECTIONS below -- one entry per behavioral statement, e.g.
 * "item1", "item2", "item3", "a3_1".."a3_4", "a4_1".."a4_3", etc.
 *
 * This file is self-contained: everything below (section text, fonts,
 * generator function) can be copied as-is into the app.
 */

const SECTIONS = [
  {
    id: 'sec1', number: '1', title: 'Demonstrates Ethical Practice',
    desc: 'Understands and consistently applies coaching ethics and standards of coaching.',
    colHead: 'Qualifier',
    items: [
      { id: 'item1', text: "1. Coach demonstrates a strong understanding and alignment with the ICF Code of Ethics." },
      { id: 'item2', text: "2. Coach consistently stays in the role of the coach, demonstrating knowledge of how to structure a coaching conversation and stays focused on future and present issues." },
      { id: 'item3', text: "3. Use key coaching skills such as trust, presence, active listening, and evoking awareness to facilitate the client's own insights." },
    ],
  },
  {
    id: 'sec2', number: '2', title: 'Embodies a Coaching Mindset',
    desc: 'Develops and maintains a mindset that is open, curious, flexible and client-centered.',
    staticNote: "Candidates' understanding of this competency is evaluated in the ICF ACC Exam.",
  },
  {
    id: 'sec3', number: '3', title: 'Establishes and Maintains Agreements',
    desc: 'Partners with the client and relevant stakeholders to create clear agreements about the coaching relationship, process, plans and goals. Establishes agreements for the overall coaching engagement as well as those for each coaching session.',
    colHead: 'Behavioral Statement',
    items: [
      { id: 'a3_1', text: "A3.1 Coach explores the client's topic with the client." },
      { id: 'a3_2', text: "A3.2 Coach and client reach agreement on what the client wants to accomplish as a session outcome." },
      { id: 'a3_3', text: "A3.3 Coach explores the significance of the coaching outcome to the client." },
      { id: 'a3_4', text: "A3.4 Coach attends to the agreed upon agenda throughout the session." },
    ],
  },
  {
    id: 'sec4', number: '4', title: 'Cultivates Trust and Safety',
    desc: 'Partners with the client to create a safe, supportive environment that allows the client to share freely. Maintains a relationship of mutual respect and trust.',
    colHead: 'Behavioral Statement',
    items: [
      { id: 'a4_1', text: "A4.1 Coach acknowledges the client's work in the session." },
      { id: 'a4_2', text: "A4.2 Coach expresses respect, support, or concern for the client." },
      { id: 'a4_3', text: "A4.3 Coach supports the client's expression of feelings, perceptions, concerns, or beliefs." },
    ],
  },
  {
    id: 'sec5', number: '5', title: 'Maintains Presence',
    desc: 'Is fully conscious and present with the client, employing a style that is open, flexible, grounded and confident.',
    colHead: 'Behavioral Statement',
    items: [
      { id: 'a5_1', text: "A5.1 Coach is observant and responsive to the client." },
      { id: 'a5_2', text: "A5.2 Coach demonstrates curiosity about the client, or their agenda, or both." },
      { id: 'a5_3', text: "A5.3 Coach provides space for the client to lead during the session." },
      { id: 'a5_4', text: "A5.4 Coach is silent to allow time for the client to reflect." },
    ],
  },
  {
    id: 'sec6', number: '6', title: 'Listens Actively',
    desc: 'Focuses on what the client is and is not saying to fully understand what is being communicated in the context of the client systems and to support client self-expression.',
    colHead: 'Behavioral Statement',
    items: [
      { id: 'a6_1', text: "A6.1 Coach listens by recognizing feelings, perceptions, challenges, or beliefs." },
      { id: 'a6_2', text: "A6.2 Coach inquires about, explores, or includes the client's use of language." },
      { id: 'a6_3', text: "A6.3 Coach summarizes or paraphrases what the client communicates to confirm the coach's understanding." },
    ],
  },
  {
    id: 'sec7', number: '7', title: 'Evokes Awareness',
    desc: 'Facilitates client insight and learning by using tools and techniques such as powerful questioning, silence, metaphor or analogy.',
    colHead: 'Behavioral Statement',
    items: [
      { id: 'a7_1', text: "A7.1 Coach supports the client in viewing the situation from different perspectives." },
      { id: 'a7_2', text: "A7.2 Coach inquires about the client's feelings, perceptions, behaviors, or beliefs." },
      { id: 'a7_3', text: "A7.3 Coach asks clear, open-ended questions, one at a time." },
    ],
  },
  {
    id: 'sec8', number: '8', title: 'Facilitates Client Growth',
    desc: 'Partners with the client to transform learning and insight into action. Promotes client autonomy in the coaching process.',
    colHead: 'Behavioral Statement',
    items: [
      { id: 'a8_1', text: "A8.1 Coach asks questions about what the client has learned during the session." },
      { id: 'a8_2', text: "A8.2 Coach supports the client to use their learning to plan next steps." },
      { id: 'a8_3', text: "A8.3 Coach supports the client to close the session." },
    ],
  },
];

const MONTSERRAT_REGULAR_B64 = "";
const MONTSERRAT_BOLD_B64 = "";

const NAVY = [0, 32, 91];
const LIGHT_BLUE = [159, 221, 249];
const GRAY = [124, 126, 127];

// ---- This is the reusable report generator. Copy it into your app. ----
function generateACCObservationReportPDF(data) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'pt', format: 'letter' });

  // Embed real Montserrat (regular + bold) instead of relying on jsPDF's
  // built-in Helvetica. MONTSERRAT_REGULAR_B64 / MONTSERRAT_BOLD_B64 are
  // base64 TTF data -- see the bottom of this file for where they come from.
  doc.addFileToVFS('Montserrat-Regular.ttf', MONTSERRAT_REGULAR_B64);
  doc.addFont('Montserrat-Regular.ttf', 'Montserrat', 'normal');
  doc.addFileToVFS('Montserrat-Bold.ttf', MONTSERRAT_BOLD_B64);
  doc.addFont('Montserrat-Bold.ttf', 'Montserrat', 'bold');

  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 40;
  let y = margin;

  function ensureRoom(neededHeight) {
    if (y + neededHeight > pageHeight - 50) {
      doc.addPage();
      y = margin;
      drawLetterhead();
    }
  }

  function drawLetterhead() {
    doc.setFont('Montserrat', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(...NAVY);
    doc.text('CoachRICE: Level 1', margin, y + 12);
    doc.setFont('Montserrat', 'bold');
    doc.setFontSize(12);
    doc.text('Associate Certified Coach (ACC) Observation Form', margin, y + 28);
    doc.setDrawColor(...GRAY);
    doc.setLineWidth(0.5);
    doc.line(margin, y + 38, pageWidth - margin, y + 38);
    y += 50;
  }

  function drawSectionHeader(section) {
    const titleText = `${section.number}. ${section.title}`;
    const descLines = doc.splitTextToSize(section.desc, pageWidth - margin * 2 - 16);
    const barHeight = 20 + descLines.length * 13;
    ensureRoom(barHeight + 60); // leave room for at least the table head too

    doc.setFillColor(...NAVY);
    doc.rect(margin, y, pageWidth - margin * 2, barHeight, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFont('Montserrat', 'bold');
    doc.setFontSize(11);
    doc.text(titleText, margin + 8, y + 15);
    doc.setFont('Montserrat', 'normal');
    doc.setFontSize(9);
    doc.text(descLines, margin + 8, y + 30);
    y += barHeight; // no gap -- the table's head row sits flush against this bar
  }

  function drawItemsTable(section) {
    const body = section.items.map(item => {
      const evRaw = (data.evidenceNotes && data.evidenceNotes[item.id]) || '';
      const contraRaw = (data.contraEvidenceNotes && data.contraEvidenceNotes[item.id]) || '';
      const noteRaw = (data.statementNotes && data.statementNotes[item.id]) || '';
      const observed = (data.observed && data.observed[item.id]) || '';

      let statementCell = item.text;
      if (noteRaw) statementCell += '\n\n' + noteRaw;
      if (evRaw || contraRaw) {
        statementCell += '\n';
        if (evRaw) statementCell += '\n' + evRaw;
        if (contraRaw) statementCell += '\nContra: ' + contraRaw;
      }
      return [statementCell, observed];
    });

    doc.autoTable({
      startY: y,
      margin: { left: margin, right: margin },
      head: [[section.colHead, 'Observed/Not Observed']],
      body,
      styles: {
        font: 'Montserrat',
        fontSize: 9,
        cellPadding: 6,
        valign: 'top',
        overflow: 'linebreak',
        textColor: [20, 20, 20],
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
      },
      headStyles: {
        fillColor: LIGHT_BLUE,
        textColor: NAVY,
        fontStyle: 'bold',
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
      },
      columnStyles: {
        0: { cellWidth: (pageWidth - margin * 2) * 0.75 },
        1: { cellWidth: (pageWidth - margin * 2) * 0.25, halign: 'left' },
      },
    });

    y = doc.lastAutoTable.finalY + 10;
  }

  function drawStaticNote(section) {
    const lines = doc.splitTextToSize(section.staticNote, pageWidth - margin * 2 - 16);
    const h = lines.length * 13 + 16;
    ensureRoom(h);
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.5);
    doc.rect(margin, y, pageWidth - margin * 2, h);
    doc.setTextColor(20, 20, 20);
    doc.setFont('Montserrat', 'normal');
    doc.setFontSize(9);
    doc.text(lines, margin + 8, y + 16);
    y += h + 8;
  }

  // --- Header ---
  drawLetterhead();
  const rowH = 26;
  const usableW = pageWidth - margin * 2;
  const blocks = [
    { label: 'Coach:', value: data.coachName || '', start: margin, labelW: 54, end: margin + usableW * 0.365 },
    { label: 'Assessor:', value: data.assessorName || 'CoachRICE Transcript Reviewer', start: margin + usableW * 0.365, labelW: 64, end: margin + usableW * 0.735 },
    { label: 'Date:', value: data.sessionDate || '', start: margin + usableW * 0.735, labelW: 40, end: margin + usableW },
  ];
  for (const b of blocks) {
    doc.setFillColor(...NAVY);
    doc.rect(b.start, y, b.labelW, rowH, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFont('Montserrat', 'bold');
    doc.setFontSize(10);
    doc.text(b.label, b.start + 6, y + 17);
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.5);
    doc.rect(b.start + b.labelW, y, b.end - (b.start + b.labelW), rowH, 'S');
    doc.setTextColor(20, 20, 20);
    doc.setFont('Montserrat', 'normal');
    let valueFontSize = 10;
    const valueBoxWidth = b.end - (b.start + b.labelW) - 12;
    while (valueFontSize > 6 && doc.getStringUnitWidth(b.value) * valueFontSize > valueBoxWidth) {
      valueFontSize -= 0.5;
    }
    doc.setFontSize(valueFontSize);
    doc.text(b.value, b.start + b.labelW + 6, y + 17);
  }
  y += rowH + 14;

  // --- Sections 1, 3-8 ---
  for (const section of SECTIONS) {
    drawSectionHeader(section);
    if (section.items) drawItemsTable(section);
    if (section.staticNote) drawStaticNote(section);
  }

  // --- Evaluation Summary ---
  ensureRoom(40);
  doc.setFont('Montserrat', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...NAVY);
  doc.text('Evaluation Summary', margin, y + 12);
  y += 22;

  doc.autoTable({
    startY: y,
    margin: { left: margin, right: margin },
    head: [['', 'Summary']],
    body: [
      ['Coaching Competency Strengths', data.summaryStrengths || ''],
      ['Suggestions for Competency Development', data.summarySuggestions || ''],
    ],
    styles: {
      font: 'Montserrat', fontSize: 9, cellPadding: 8, valign: 'top',
      overflow: 'linebreak', textColor: [20, 20, 20], lineColor: [0, 0, 0], lineWidth: 0.5,
    },
    // minCellHeight lives on bodyStyles, not the shared styles object --
    // putting it on `styles` was applying it to the head row too, which is
    // why "Summary" got a huge ~70pt-tall header for no reason.
    bodyStyles: { minCellHeight: 70 },
    headStyles: { fillColor: NAVY, textColor: [255, 255, 255], fontStyle: 'bold' },
    columnStyles: {
      0: { cellWidth: (pageWidth - margin * 2) * 0.32, fontStyle: 'bold' },
      1: { cellWidth: (pageWidth - margin * 2) * 0.68 },
    },
  });

  return doc;
}
// ---- End of reusable code ----
// If this file is used as an ES module (e.g. with a bundler), uncomment:
// export { generateACCObservationReportPDF, SECTIONS };

export { generateACCObservationReportPDF };
